import { Link } from 'react-router-dom';
import type { InputRole, JobView } from '../lib/api';
import { useAuth } from '../lib/auth';
import { isTerminal, outputItems } from '../lib/jobs';

const INPUT_ROLE: Record<InputRole, string> = {
  image: 'Input image',
  mask: 'Mask',
  first_frame: 'First frame',
  last_frame: 'Last frame',
  reference_image: 'Reference image',
};

/** Where "Animate this" goes: the video Studio, with this output as its first frame. Nothing is generated by opening it. */
export function animateLink(jobId: string, index: number): string {
  return `/create/video?animate=${encodeURIComponent(jobId)}&output=${index}`;
}

/** Whether a finished image job's output can be animated: inputs are on, and the file is still there. */
export function useCanAnimate(job: JobView): boolean {
  const { user } = useAuth();
  return user?.inputs?.enabled === true && job.modality === 'IMAGE' && job.status === 'DONE' && !job.purged;
}

/**
 * The images a job was given, beside what it made: each with what it was to
 * the job. An input whose file is gone says so. Nothing for a job with none.
 */
export function JobInputs({ job, className = '', size = 'md' }: {
  job: JobView;
  className?: string;
  size?: 'sm' | 'md';
}) {
  const inputs = job.inputs ?? [];
  if (inputs.length === 0) return null;
  const box = size === 'sm' ? 'w-12' : 'w-20';
  return (
    <div className={className} data-job-inputs>
      <p className="text-xs font-semibold text-fg-subtle">{inputs.length === 1 ? 'Input' : 'Inputs'}</p>
      <ul aria-label="Inputs" className="mt-1.5 flex flex-wrap gap-3">
        {inputs.map((input, i) => (
          // eslint-disable-next-line react/no-array-index-key -- a job's inputs are fixed, and two may be the same file
          <li key={i} className={box}>
            {input.url ? (
              <a href={input.url} target="_blank" rel="noopener noreferrer" aria-label={`Open the ${INPUT_ROLE[input.role].toLowerCase()} in full`}>
                <img src={input.url} alt={INPUT_ROLE[input.role]} loading="lazy"
                     className="aspect-square w-full rounded-md bg-bg-muted object-cover" />
              </a>
            ) : (
              <div className="flex aspect-square w-full items-center justify-center rounded-md border border-dashed border-border-strong p-1 text-center text-[10px] text-fg-faint">
                Deleted
              </div>
            )}
            {size === 'md' && <p className="mt-1 text-[11px] leading-tight text-fg-subtle">{INPUT_ROLE[input.role]}</p>}
          </li>
        ))}
      </ul>
    </div>
  );
}

function truncate(s: string, max: number): string {
  return s.length > max ? `${s.slice(0, max - 1)}…` : s;
}

/** Every file a job produced, each with a Download link. */
export function JobOutputs({ job, className = '', onDescribe }: {
  job: JobView;
  className?: string;
  /** "Describe as prompt" on an image output, where the page offers it. */
  onDescribe?: (url: string) => void;
}) {
  const canAnimate = useCanAnimate(job);
  if (job.purged) {
    return (
      <p className={`text-sm text-fg-muted ${className}`}>
        The files for this generation were deleted at the end of the retention period.
      </p>
    );
  }
  const items = outputItems(job);
  if (items.length === 0) {
    return <p className={`text-sm text-fg-muted ${className}`}>No files came back for this generation.</p>;
  }

  return (
    <ul className={`grid gap-4 ${items.length > 1 ? 'sm:grid-cols-2' : ''} ${className}`}>
      {items.map((item, i) => {
        const kind = item.kind === 'video' ? 'video' : 'image';
        const which = items.length > 1 ? `${kind} ${i + 1} of ${items.length}` : kind;
        const name = `Generated ${which}${job.prompt ? `: ${truncate(job.prompt, 120)}` : ''}`;
        return (
          <li key={item.key}>
            <figure>
              {item.kind === 'video' ? (
                <video
                  src={item.url}
                  controls
                  playsInline
                  preload="metadata"
                  aria-label={name}
                  className="w-full rounded-md bg-black"
                />
              ) : (
                <img src={item.url} alt={name} className="w-full rounded-md bg-bg-muted" />
              )}
              <figcaption className="mt-2 flex items-start justify-between gap-3">
                <span className="text-xs text-fg-subtle">
                  {item.revisedPrompt && <>Revised prompt: {item.revisedPrompt}</>}
                </span>
                {/* A signed link on the storage host: cross-origin, so the
                    browser may open it in a tab rather than save it. */}
                <span className="flex shrink-0 flex-wrap justify-end gap-2">
                  {item.kind === 'image' && onDescribe && (
                    <button type="button" className="btn btn-ghost btn-sm" onClick={() => onDescribe(item.url)}>
                      Describe as prompt<span className="sr-only">: {which}</span>
                    </button>
                  )}
                  {item.kind === 'image' && canAnimate && (
                    <Link to={animateLink(job.id, Number(item.key))} className="btn btn-secondary btn-sm"
                          aria-label={`Animate ${which}`}>
                      Animate this
                    </Link>
                  )}
                  <a
                    href={item.url}
                    download
                    target="_blank"
                    rel="noopener noreferrer"
                    aria-label={`Download ${which}`}
                    className="btn btn-secondary btn-sm"
                  >
                    Download
                  </a>
                </span>
              </figcaption>
            </figure>
          </li>
        );
      })}
    </ul>
  );
}

function thumbText(job: JobView): string {
  if (job.purged) return 'Files deleted';
  if (!isTerminal(job.status)) return 'In progress…';
  if (job.status === 'FAILED') return 'Failed';
  if (job.status === 'CANCELLED') return 'Cancelled';
  return 'No preview';
}

/**
 * A job's first output as a square thumbnail. Images load lazily; a video
 * loads only its metadata, enough to show a frame.
 */
export function JobThumb({ job }: { job: JobView }) {
  const first = outputItems(job)[0];
  return (
    <div className="aspect-square overflow-hidden bg-bg-muted">
      {first?.kind === 'video' ? (
        <video
          src={`${first.url}#t=0.1`}
          preload="metadata"
          muted
          playsInline
          aria-hidden="true"
          tabIndex={-1}
          className="h-full w-full object-cover"
        />
      ) : first ? (
        <img src={first.url} alt="" loading="lazy" decoding="async" className="h-full w-full object-cover" />
      ) : (
        <div className="flex h-full items-center justify-center p-3 text-center text-xs text-fg-faint">
          {thumbText(job)}
        </div>
      )}
    </div>
  );
}
